class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        cars = sorted(zip(position, speed), reverse=True)
        while True:
            best_t, idx = float('inf'), -1
            for i in range(len(cars) - 1):
                p1, s1 = cars[i]
                p2, s2 = cars[i + 1]
                if s2 > s1:
                    t = (p1 - p2) / (s2 - s1)
                    if t < best_t:
                        best_t, idx = t, i
            if idx == -1:
                return len(cars)
            p1, s1 = cars[idx]
            p2, s2 = cars[idx + 1]
            meet = p2 + s2 * best_t
            cars[idx] = (meet, min(s1, s2))
            del cars[idx + 1]

