    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        int n = position.size();
        vector<pair<int,int>> cars;
        for (int i = 0; i < n; i++) cars.push_back({position[i], speed[i]});
        sort(cars.rbegin(), cars.rend());
        while (true) {
            double bestT = 1e18; int idx = -1;
            for (int i = 0; i + 1 < (int)cars.size(); i++) {
                if (cars[i+1].second > cars[i].second) {
                    double t = (double)(cars[i].first - cars[i+1].first) / (cars[i+1].second - cars[i].second);
                    if (t < bestT) { bestT = t; idx = i; }
                }
            }
            if (idx == -1) return cars.size();
            double meet = cars[idx+1].first + (double)cars[idx+1].second * bestT;
            cars[idx] = {(int)llround(meet * 1000000), min(cars[idx].second, cars[idx+1].second)};
            cars.erase(cars.begin() + idx + 1);
        }
    }
};

