class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        int[][] cars = new int[n][2];
        for (int i = 0; i < n; i++) { cars[i][0] = position[i]; cars[i][1] = speed[i]; }
        Arrays.sort(cars, (a, b) -> b[0] - a[0]);
        while (true) {
            double bestT = Double.MAX_VALUE; int idx = -1;
            for (int i = 0; i + 1 < cars.length; i++) {
                if (cars[i+1][1] > cars[i][1]) {
                    double t = (double)(cars[i][0] - cars[i+1][0]) / (cars[i+1][1] - cars[i][1]);
                    if (t < bestT) { bestT = t; idx = i; }
                }
            }
            if (idx == -1) return cars.length;
            double meet = cars[idx+1][0] + (double) cars[idx+1][1] * bestT;
            cars[idx][0] = (int) Math.round(meet * 1000000);
            cars[idx][1] = Math.min(cars[idx][1], cars[idx+1][1]);
            int[][] next = new int[cars.length - 1][2];
            int k = 0;
            for (int i = 0; i < cars.length; i++) if (i != idx + 1) next[k++] = cars[i];
            cars = next;
        }
    }
}

