        if (idx === -1) return cars.length;
        const meet = cars[idx + 1][0] + cars[idx + 1][1] * bestT;
        cars[idx] = [Math.round(meet * 1e6), Math.min(cars[idx][1], cars[idx + 1][1])];
        cars.splice(idx + 1, 1);
